  current_setting('truth.session_id'), 158,
  to_jsonb($t$No sentence of the operator on ASK 587 is in the record W3 read for this row. His part is the card press: "Write ASK 587", 23:17 CST 2026-11-23, W4's thread (Wall 11360; audit 41171). His statement of 23:00 CST in the W3 thread ("this next fix will mostly be around the judges reasoning...") is the reason the form fixes were split from ASK 586 into ASK 587 (plan587.md head).$t$::text),
  $j${"answer": "Write ASK 587", "source": "Wall 11360; audit 41171", "thread": "W4", "question": "not in the record W3 read (the card is in W4's thread; Wall 11360 gives its label only)", "press_time": "23:17 CST"}$j$::jsonb,
  'W4',
  $j${"md5": "903faa78", "note": "rev 3; rev 1 kept as plan587_rev1.md 30b72a6c, rev 2 as plan587_rev2.md d974b63c; rev 0 was ask586/w4/plan586.md 4a9ecc3e", "path": "ask587/w4/plan587.md", "commit": "52c017f4", "source": "md5sum by W3 (903faa782cd2fd740229720eaf7e099a); Wall 11355, 11357"}$j$::jsonb,
  $j$[{"md5": "d643fc34", "note": "the engine as built; graded and read back node by node", "path": "target_engine_586 (build target, engine)", "source": "plan section 5; Wall 11355, 11357, 11361"}, {"md5": "4476e122", "note": "the child as built", "path": "target_child_586 (build target, child)", "source": "plan section 5; Wall 11355, 11357, 11361"}, {"md5": "3f4e28bf", "note": "the build script", "path": "a586_w4/build/build586.cjs", "source": "plan section 5; not md5-checked by W3 (git only)"}, {"md5": "597906b4", "note": "the test, 40 cases", "path": "a586_w4/build/t586.cjs", "source": "plan section 6; Wall 11355"}, {"md5": "486a114e", "note": "t586 output on the fresh fetch at the write; the same md5 as out_t586.txt in the plan", "path": "ask587/w4/write/t586_at_write.txt", "source": "md5sum by W3 (486a114e98cb07091e5fbc75446764f5)"}, {"md5": "18b43d2a", "note": "sbApply2024 run in its built scope", "path": "gatefn.cjs", "source": "plan section 3b"}, {"md5": "3fd8778f", "note": "acorn scope check", "path": "scope587.cjs", "source": "plan section 3b"}, {"md5": "fa65147f", "note": "PUT body, engine", "path": "ask587/w4/write/put_eng587.json", "source": "md5sum by W3"}, {"md5": "94519e1b", "note": "PUT body, child", "path": "ask587/w4/write/put_child587.json", "source": "md5sum by W3"}, {"md5": "20538828", "note": "fetch-back, engine", "path": "ask587/w4/write/fetchback_eng587.json", "source": "md5sum by W3"}, {"md5": "9fcdb69e", "note": "fetch-back, child", "path": "ask587/w4/write/fetchback_child587.json", "source": "md5sum by W3"}, {"md5": "28604493", "note": "fresh fetch before the write; the same md5 as ask585/w4/write/fetchback_eng585.json (row 153)", "path": "ask587/w4/write/prewrite_eng587.json", "source": "md5sum by W3"}, {"md5": "dd4fd85c", "note": "fresh fetch before the write, child", "path": "ask587/w4/write/prewrite_child587.json", "source": "md5sum by W3"}, {"md5": "12182948", "note": "the write script", "path": "ask587/w4/write/write587.sh", "sourc